'use client';

import { useState } from 'react';
import { MagnifyingGlassIcon, PlusIcon, PencilIcon, TrashIcon, XMarkIcon, ExclamationTriangleIcon } from '@heroicons/react/24/outline';
import { createDocumentType, updateDocumentType, deleteDocumentType } from '@/app/lib/actions';

type DocType = { id: string; name: string; category_id: string; category_name: string; created_at: string; };
type Category = { id: string; name: string; };

function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: React.ReactNode }) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-md mx-4">
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100">
          <h2 className="text-base font-bold text-slate-800">{title}</h2>
          <button onClick={onClose} className="p-1.5 rounded-lg text-slate-400 hover:text-slate-600 hover:bg-slate-100 transition-all">
            <XMarkIcon className="w-5 h-5" />
          </button>
        </div>
        <div className="px-6 py-5">{children}</div>
      </div>
    </div>
  );
}

function DeleteModal({ item, onConfirm, onCancel, loading }: { item: DocType; onConfirm: () => void; onCancel: () => void; loading: boolean; }) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onCancel} />
      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-sm mx-4">
        <div className="px-6 pt-6 pb-5 flex flex-col items-center text-center">
          <div className="w-14 h-14 rounded-full bg-red-100 flex items-center justify-center mb-4">
            <ExclamationTriangleIcon className="w-7 h-7 text-red-500" />
          </div>
          <h2 className="text-base font-bold text-slate-800 mb-1">Konfirmasi Hapus</h2>
          <p className="text-sm text-slate-500">Kamu yakin ingin menghapus jenis dokumen</p>
          <p className="text-sm font-bold text-slate-700 mt-1">"{item.name}"?</p>
          <p className="text-xs text-red-400 mt-3 bg-red-50 px-3 py-2 rounded-lg w-full">Tindakan ini tidak dapat dibatalkan.</p>
        </div>
        <div className="flex gap-2 px-6 pb-6">
          <button onClick={onCancel} className="flex-1 px-4 py-2.5 text-sm font-medium border border-slate-200 rounded-xl text-slate-600 hover:bg-slate-50 transition-all">Batal</button>
          <button onClick={onConfirm} disabled={loading} className="flex-1 px-4 py-2.5 text-sm font-bold bg-red-600 text-white rounded-xl hover:bg-red-700 disabled:opacity-50 transition-all active:scale-95">
            {loading ? 'Menghapus...' : 'Ya, Hapus'}
          </button>
        </div>
      </div>
    </div>
  );
}

function TypeForm({ defaultValues, categories, onSubmit, onCancel, loading, error }: {
  defaultValues?: DocType; categories: Category[];
  onSubmit: (e: React.FormEvent<HTMLFormElement>) => void;
  onCancel: () => void; loading: boolean; error: string;
}) {
  return (
    <form onSubmit={onSubmit} className="space-y-4">
      <div>
        <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wide mb-1.5">Kategori</label>
        <select name="category_id" defaultValue={defaultValues?.category_id ?? ''}
          className="w-full border border-slate-200 rounded-xl px-3.5 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/10 transition-all bg-white" required>
          <option value="" disabled>Pilih kategori...</option>
          {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
        </select>
      </div>
      <div>
        <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wide mb-1.5">Nama Jenis Dokumen</label>
        <input name="name" defaultValue={defaultValues?.name} required placeholder="contoh: Instruksi Kerja"
          className="w-full border border-slate-200 rounded-xl px-3.5 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/10 transition-all" />
      </div>
      {error && <div className="bg-red-50 border border-red-200 text-red-600 text-sm rounded-xl px-4 py-3">{error}</div>}
      <div className="flex gap-2 justify-end pt-1">
        <button type="button" onClick={onCancel} className="px-4 py-2.5 text-sm font-medium border border-slate-200 rounded-xl text-slate-600 hover:bg-slate-50 transition-all">Batal</button>
        <button type="submit" disabled={loading} className="px-5 py-2.5 text-sm font-bold bg-blue-600 text-white rounded-xl hover:bg-blue-700 disabled:opacity-50 transition-all active:scale-95">
          {loading ? 'Menyimpan...' : defaultValues ? 'Update' : 'Simpan'}
        </button>
      </div>
    </form>
  );
}

export default function DocumentTypesTable({ types, categories }: { types: DocType[]; categories: Category[] }) {
  const [search, setSearch] = useState('');
  const [showCreate, setShowCreate] = useState(false);
  const [editItem, setEditItem] = useState<DocType | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<DocType | null>(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const filtered = types.filter(t =>
    t.name.toLowerCase().includes(search.toLowerCase()) ||
    t.category_name.toLowerCase().includes(search.toLowerCase())
  );

  async function handleCreate(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setLoading(true); setError('');
    const result = await createDocumentType(new FormData(e.currentTarget));
    setLoading(false);
    if (result?.error) setError(result.error);
    else setShowCreate(false);
  }

  async function handleUpdate(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!editItem) return;
    setLoading(true); setError('');
    const result = await updateDocumentType(editItem.id, new FormData(e.currentTarget));
    setLoading(false);
    if (result?.error) setError(result.error);
    else setEditItem(null);
  }

  async function handleDelete() {
    if (!deleteTarget) return;
    setLoading(true);
    const result = await deleteDocumentType(deleteTarget.id);
    setLoading(false);
    if (result?.error) setError(result.error);
    else setDeleteTarget(null);
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div className="relative w-full max-w-sm">
          <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
          <input type="text" placeholder="Cari jenis dokumen..."
            className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-[10px] text-sm focus:border-blue-500 outline-none transition-all shadow-sm"
            onChange={(e) => setSearch(e.target.value)} />
        </div>
        <button onClick={() => { setShowCreate(true); setEditItem(null); setError(''); }}
          className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-[10px] text-[13.5px] font-bold hover:bg-blue-700 transition-all shadow-md shadow-blue-500/20 active:scale-95">
          <PlusIcon className="w-4 h-4" />
          TAMBAH JENIS DOKUMEN
        </button>
      </div>

      {error && <div className="p-3 bg-red-50 border border-red-200 text-red-600 rounded-[10px] text-sm">{error}</div>}

      <div className="bg-white border border-slate-200 rounded-[12px] overflow-hidden shadow-sm">
        <table className="w-full border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200">
              <th className="text-left px-6 py-3 text-[11px] font-bold text-slate-400 uppercase tracking-wider">Nama Jenis</th>
              <th className="text-left px-6 py-3 text-[11px] font-bold text-slate-400 uppercase tracking-wider">Kategori</th>
              <th className="text-right px-6 py-3 text-[11px] font-bold text-slate-400 uppercase tracking-wider">Aksi</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filtered.map((type) => (
              <tr key={type.id} className="hover:bg-blue-50/50 transition-colors group">
                <td className="px-6 py-4 font-medium text-slate-800 text-[13.5px]">{type.name}</td>
                <td className="px-6 py-4">
                  <span className="px-3 py-1 rounded-full text-[10px] font-bold bg-blue-100 text-blue-600">
                    {type.category_name}
                  </span>
                </td>
                <td className="px-6 py-4 text-right">
                  <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button onClick={() => { setEditItem(type); setShowCreate(false); setError(''); }}
                      className="p-2 bg-white border border-slate-200 rounded-lg text-slate-400 hover:text-blue-600 hover:border-blue-200 shadow-sm transition-all">
                      <PencilIcon className="w-4 h-4" />
                    </button>
                    <button onClick={() => { setDeleteTarget(type); setError(''); }}
                      className="p-2 bg-white border border-slate-200 rounded-lg text-slate-400 hover:text-red-600 hover:border-red-200 shadow-sm transition-all">
                      <TrashIcon className="w-4 h-4" />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr><td colSpan={3} className="px-6 py-10 text-center text-slate-400 text-sm">Tidak ada data ditemukan.</td></tr>
            )}
          </tbody>
        </table>
      </div>

      {showCreate && (
        <Modal title="Tambah Jenis Dokumen" onClose={() => setShowCreate(false)}>
          <TypeForm categories={categories} onSubmit={handleCreate} onCancel={() => setShowCreate(false)} loading={loading} error={error} />
        </Modal>
      )}

      {editItem && (
        <Modal title="Edit Jenis Dokumen" onClose={() => setEditItem(null)}>
          <TypeForm defaultValues={editItem} categories={categories} onSubmit={handleUpdate} onCancel={() => setEditItem(null)} loading={loading} error={error} />
        </Modal>
      )}

      {deleteTarget && (
        <DeleteModal item={deleteTarget} onConfirm={handleDelete} onCancel={() => setDeleteTarget(null)} loading={loading} />
      )}
    </div>
  );
}
